    if d['fz_N'] > 0.3:
        contact=(d['z_mm'], d['fz_N']); print('contact', contact); break
    if d['z_mm'] < 113:
        print('no contact?'); break
# load in 0.5 steps to 38 N
load=[]
for i in range(30):
    r=workcell.call('arm','step','-0.5')
    print(r.text.strip())
    d=r.data; load.append((d['z_mm'], d['fz_N']))
    if d['fz_N'] >= 38.0:
        print('load limit'); break
    if d['z_mm'] <= 106.0:
        print('z limit'); break
# unload in +0.5 steps until fz<0.5
unload=[]
for i in range(30):
    r=workcell.call('arm','step','+0.5')
    print(r.text.strip())
    d=r.data; unload.append((d['z_mm'], d['fz_N']))
    if d['fz_N'] <= 0.5:
        print('unloaded'); break
    if d['z_mm'] >= 116.0:
        print('z high'); break
with open('/home/robot/load_data2.csv','w',newline='') as fp:
    w=csv.writer(fp); w.writerow(['phase','z_mm','Fz_N'])
    if contact: w.writerow(['contact', contact[0], contact[1]])
    for z,f in load: w.writerow(['load',z,f])
    for z,f in unload: w.writerow(['unload',z,f])
print('saved contact',contact,'load',len(load),'unload',len(unload))
